using System.Text.Json.Serialization;
using System.Threading.RateLimiting;
using Microsoft.AspNetCore.Identity;
using Microsoft.AspNetCore.DataProtection;
using Microsoft.AspNetCore.RateLimiting;
using Microsoft.EntityFrameworkCore;
using TrainingManagement.Api.Data;
using TrainingManagement.Api.Infrastructure;
using TrainingManagement.Api.Models;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddSingleton<ApplicationHealth>();
if (builder.Environment.IsDevelopment())
{
    // Local secrets are generated by the development script, never tracked.
    // Environment variables and CLI arguments retain the highest precedence.
    var secretsPath = Path.GetFullPath("../.runtime/development.secrets.json", builder.Environment.ContentRootPath);
    builder.Configuration.AddJsonFile(secretsPath, optional: true, reloadOnChange: false)
        .AddEnvironmentVariables().AddCommandLine(args);
}

builder.Services.AddHttpContextAccessor();
builder.Services.AddDataProtection().SetApplicationName("TrainingManagement")
    .PersistKeysToFileSystem(new DirectoryInfo(builder.Configuration["DataProtection:KeysPath"]
        ?? Path.GetFullPath("../.runtime/keys", builder.Environment.ContentRootPath)));
builder.Services.AddHttpClient("integrations", client => client.Timeout = TimeSpan.FromSeconds(15))
    .ConfigurePrimaryHttpMessageHandler(() => new HttpClientHandler { AllowAutoRedirect = false });
builder.Services.AddScoped<AdvancedJobs>();
builder.Services.AddScoped<WebhookService>();
builder.Services.AddScoped<HrSyncService>();
builder.Services.AddScoped<DataScope>();
builder.Services.AddScoped<AdvancedAccess>();
builder.Services.AddScoped<BudgetService>();
builder.Services.AddScoped<ScheduleService>();
builder.Services.AddScoped<WaitlistService>();
builder.Services.AddScoped<WorkflowService>();
builder.Services.AddScoped<TrainingService>();
builder.Services.AddScoped<ReportingService>();
builder.Services.AddScoped<EmployeeImportService>();
builder.Services.AddScoped<EnterpriseJobs>();
builder.Services.AddHostedService<EnterpriseWorker>();
builder.Services.AddControllers().AddJsonOptions(options => {
    options.JsonSerializerOptions.Converters.Add(new JsonStringEnumConverter(allowIntegerValues: false));
    options.JsonSerializerOptions.Converters.Add(new UtcDateTimeConverter());
});
builder.Services.AddProblemDetails();
builder.Services.AddExceptionHandler<ApiExceptionHandler>();
builder.Services.AddOpenApi();
builder.Services.AddCors(options => options.AddDefaultPolicy(policy =>
    policy.WithOrigins(builder.Configuration.GetSection("Cors:Origins").Get<string[]>()
        ?? ["http://localhost:4200", "http://127.0.0.1:4200"])
        .AllowAnyHeader().AllowAnyMethod().WithExposedHeaders("X-Total-Count")));
builder.Services.AddSingleton<MutationGate>();
builder.Services.AddTrainingAuthentication(JwtSettings.Load(builder.Configuration));
var registerPermitLimit = builder.Configuration.GetValue("RateLimits:RegisterPermitLimit", 5);
if (registerPermitLimit is < 1 or > 100)
    throw new InvalidOperationException("RateLimits:RegisterPermitLimit 必須介於 1 與 100 之間。");
builder.Services.AddRateLimiter(options =>
{
    options.RejectionStatusCode = StatusCodes.Status429TooManyRequests;
    options.AddPolicy("login", context => RateLimitPartition.GetFixedWindowLimiter(
        context.Connection.RemoteIpAddress?.ToString() ?? "unknown", _ => new FixedWindowRateLimiterOptions
        {
            PermitLimit = 10, Window = TimeSpan.FromMinutes(1), QueueLimit = 0, AutoReplenishment = true
        }));
    options.AddPolicy("register", context => RateLimitPartition.GetFixedWindowLimiter(
        context.Connection.RemoteIpAddress?.ToString() ?? "unknown", _ => new FixedWindowRateLimiterOptions
        {
            PermitLimit = registerPermitLimit, Window = TimeSpan.FromMinutes(1), QueueLimit = 0, AutoReplenishment = true
        }));
    options.OnRejected = async (context, cancellationToken) =>
    {
        context.HttpContext.Response.Headers.RetryAfter = "60";
        await Results.Problem(statusCode: 429, title: "請求過於頻繁，請稍後再試。")
            .ExecuteAsync(context.HttpContext);
    };
});

var connection = builder.Configuration.GetConnectionString("TrainingDatabase")
    ?? throw new InvalidOperationException("請設定 SQL Server ConnectionStrings:TrainingDatabase。");
builder.Services.AddDbContext<TrainingDbContext>(options => options.UseSqlServer(connection));

builder.Services.AddAuthentication().AddScheme<Microsoft.AspNetCore.Authentication.AuthenticationSchemeOptions,IntegrationAuthentication>(IntegrationAuthentication.SchemeName,_=>{});
builder.Services.AddAuthorization(options=>{foreach(var scope in IntegrationAuthentication.AllowedScopes)options.AddPolicy("client:"+scope,policy=>policy.RequireAuthenticatedUser().RequireClaim("client_scope",scope));});
var app = builder.Build();
app.Use(async (context, next) => {
    var started = System.Diagnostics.Stopwatch.GetTimestamp();
    try { await next(); }
    finally { app.Services.GetRequiredService<ApplicationHealth>().Observe(context.Response.StatusCode,
        System.Diagnostics.Stopwatch.GetElapsedTime(started).TotalMilliseconds); }
});
app.UseExceptionHandler();
if (!app.Environment.IsDevelopment()) { app.UseHsts(); app.UseHttpsRedirection(); }
app.Use(async (context, next) => {
    context.Response.Headers.XContentTypeOptions = "nosniff";
    context.Response.Headers["Referrer-Policy"] = "same-origin";
    context.Response.Headers["X-Frame-Options"] = "DENY";
    if (context.Request.Path.StartsWithSegments("/api")) context.Response.Headers.CacheControl = "no-store";
    await next();
});
if (Directory.Exists(Path.Combine(app.Environment.ContentRootPath, "wwwroot"))) { app.UseDefaultFiles(); app.UseStaticFiles(); }
app.UseStatusCodePages(async context =>
    await Results.Problem(statusCode: context.HttpContext.Response.StatusCode,
        title: context.HttpContext.Response.StatusCode switch
        {
            401 => "請先登入。", 403 => "您沒有執行此操作的權限。",
            404 => "找不到指定的資源。", _ => "無法完成此請求。"
        })
        .ExecuteAsync(context.HttpContext));
app.UseCors();
app.UseRateLimiter();
app.UseAuthentication();
app.UseAuthorization();
app.MapControllers();
app.MapGet("/api/health/ready", async (TrainingDbContext db, CancellationToken ct) =>
    await db.Database.CanConnectAsync(ct) ? Results.Ok(new { status = "ready" }) : Results.StatusCode(503)).AllowAnonymous();
app.MapGet("/api/health", () => Results.Ok(new { status = "ok", service = "TrainingManagement.Api" }))
    .WithName("Health").AllowAnonymous();
if (app.Environment.IsDevelopment()) app.MapOpenApi();
app.MapFallback("/api/{**path}", () => Results.Problem(statusCode: 404, title: "找不到 API。"));
if (Directory.Exists(Path.Combine(app.Environment.ContentRootPath, "wwwroot"))) app.MapFallbackToFile("index.html").AllowAnonymous();

await using (var scope = app.Services.CreateAsyncScope())
{
    var db = scope.ServiceProvider.GetRequiredService<TrainingDbContext>();
    if (builder.Configuration.GetValue("Database:AutoMigrate", app.Environment.IsDevelopment())) await db.Database.MigrateAsync();
    else if ((await db.Database.GetPendingMigrationsAsync()).Any()) throw new InvalidOperationException("資料庫尚未升級，請先執行發布包的 migrate.sql。");
    await BootstrapAdmin.SeedAsync(db, builder.Configuration,
        scope.ServiceProvider.GetRequiredService<IPasswordHasher<AppUser>>());
    var legacyPath = builder.Configuration["LegacyImportPath"];
    if (!string.IsNullOrWhiteSpace(legacyPath))
        await LegacyImport.ImportAsync(db, Path.GetFullPath(legacyPath, builder.Environment.ContentRootPath));
    if (app.Environment.IsDevelopment() && builder.Configuration.GetValue("SeedDemoData", true))
        await DemoData.SeedAsync(db);
    await EnterpriseBootstrap.Initialize(db);
}

await app.RunAsync();

